  `referencia` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `nombre` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `precio_uni` decimal(8, 4) NULL DEFAULT NULL,
  `iva` int NULL DEFAULT 0,
  `stock` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `servicio` int NULL DEFAULT 0,
  `inventario` int NULL DEFAULT 0,
  `producto_terminado` int NULL DEFAULT 0,
  `peso` decimal(8, 5) NULL DEFAULT NULL,
  `categoria` int NULL DEFAULT NULL,
  `codigo_aux` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0',
  `codigo_bar` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0',
  `id_empresa` int NULL DEFAULT NULL,
  `foto` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `marca` int NULL DEFAULT NULL,
  `modelo` varchar(11) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '',
  `uni_medida` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'UNI',
  `color` int NULL DEFAULT NULL,
  `genero` int NULL DEFAULT NULL,
  `estado` int NULL DEFAULT NULL,
  `sucursal` int NULL DEFAULT NULL,
  `RFID` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `fecha_creacion` date NULL DEFAULT NULL,
  `descripcion2` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `max` int NULL DEFAULT 0,
  `min` int NULL DEFAULT 0,
  `serie_pro` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '',
  `promocion` int NULL DEFAULT 0,
  `materia_prima` int NULL DEFAULT 0,
  `paquetes` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `xpaquetes` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `sueltos` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  PRIMARY KEY (`id_productos`) USING BTREE,
  INDEX `referencia`(`referencia` ASC) USING BTREE,
  INDEX `FK_EMPRESA_PRODUCTO`(`id_empresa` ASC) USING BTREE,
  INDEX `FK_CATEGORIA_PRODUCTO`(`categoria` ASC) USING BTREE,
  INDEX `FK_MARCA_PROPDUCTO`(`marca` ASC) USING BTREE,
  INDEX `FK_GENERO_PRODUCTO`(`genero` ASC) USING BTREE,
  INDEX `FK_COLOR_PRODUCTO`(`color` ASC) USING BTREE,
  INDEX `FK_ESTADO_PRODUCTO`(`estado` ASC) USING BTREE,
  INDEX `FK_SUCURSAL_PRODUCTO`(`sucursal` ASC) USING BTREE,
  CONSTRAINT `productos_ibfk_1` FOREIGN KEY (`categoria`) REFERENCES `categoria` (`id_categoria`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `productos_ibfk_2` FOREIGN KEY (`color`) REFERENCES `colores` (`ID_COLORES`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `productos_ibfk_3` FOREIGN KEY (`id_empresa`) REFERENCES `empresa` (`id_empresa`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `productos_ibfk_4` FOREIGN KEY (`estado`) REFERENCES `estado` (`ID_ESTADO`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `productos_ibfk_5` FOREIGN KEY (`genero`) REFERENCES `genero` (`ID_GENERO`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `productos_ibfk_6` FOREIGN KEY (`marca`) REFERENCES `marcas` (`ID_MARCA`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `productos_ibfk_7` FOREIGN KEY (`sucursal`) REFERENCES `sucursales` (`id_sucursal`) ON DELETE NO ACTION ON UPDATE NO ACTION
) ENGINE = InnoDB AUTO_INCREMENT = 3713 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

