-- Procedure structure for sp_eliminar_empresa_datos
-- ----------------------------
DROP PROCEDURE IF EXISTS `sp_eliminar_empresa_datos`;
delimiter ;;
CREATE PROCEDURE `sp_eliminar_empresa_datos`(IN `ID_EMPRESA` tinyint)
BEGIN

-- SELECT * from lineas_factura WHERE id_factura  in (SELECT id_factura FROM facturas WHERE id_empresa = `ID_EMPRESA`);
DELETE  from lineas_factura WHERE id_factura  in (SELECT id_factura FROM facturas WHERE id_empresa = `ID_EMPRESA` );
SELECT "Paso de lineas_factura";
-- SELECT id_factura FROM facturas WHERE id_empresa = 34
DELETE FROM facturas WHERE id_empresa = `ID_EMPRESA` ;
SELECT "Paso de facturas";

-- SELECT * FROM codigos_secuenciales WHERE id_empresa = 34
DELETE FROM codigos_secuenciales WHERE id_empresa = `ID_EMPRESA` ;
SELECT "Paso de codigos_secuenciales";

-- SELECT * FROM productos WHERE id_empresa = 34
DELETE FROM productos WHERE id_empresa = `ID_EMPRESA` ;
SELECT "Paso de productos";


-- SELECT * FROM accesos_empresa WHERE usuario in (SELECT id_usuario FROM usuario WHERE id_empresa = `ID_EMPRESA`);
DELETE FROM accesos_empresa WHERE usuario in (SELECT id_usuario FROM usuario WHERE id_empresa = `ID_EMPRESA` );

-- SELECT * FROM accesos_empresa WHERE empresa = 34
DELETE FROM accesos_empresa WHERE empresa = `ID_EMPRESA` ;
SELECT "Paso de accesos_empresa";

-- SELECT * FROM usuario WHERE id_empresa = 34
DELETE FROM usuario WHERE id_empresa = `ID_EMPRESA` ;
SELECT "Paso de usuario";

-- SELECT * FROM sucursales WHERE empresa = 34
DELETE FROM sucursales WHERE empresa = `ID_EMPRESA` ;
SELECT "Paso de sucursales";

-- SELECT * FROM cliente WHERE id_empresa = 34
DELETE FROM cliente WHERE id_empresa = `ID_EMPRESA` ;
SELECT "Paso de cliente";

-- SELECT * FROM categoria WHERE empresa = 34
DELETE FROM categoria WHERE empresa = `ID_EMPRESA` ;
SELECT "Paso de categoria";

-- SELECT * FROM forma_pago WHERE id_empresa = 34
DELETE FROM forma_pago WHERE id_empresa = `ID_EMPRESA` ;
SELECT "Paso de forma_pago";

-- SELECT * FROM tipo_usuario WHERE empresa = 34
DELETE FROM tipo_usuario WHERE empresa = `ID_EMPRESA` ;
SELECT "Paso de tipo_usuario";

-- SELECT * FROM empresa WHERE id_empresa = 34
DELETE FROM empresa WHERE id_empresa = `ID_EMPRESA` ;
SELECT "Paso de empresa";



END
;;
delimiter ;

SET FOREIGN_KEY_CHECKS = 1;
